"""C3: a burst crossing a 30-minute clock line stays one case; a gap over 30 min opens a new one."""
import unittest
from decimal import Decimal

from consumers.run import choose_case

T0 = 1793955000.0                       # 09:29:50 on some day: 10 s before a :30 clock line


class C3Episodes(unittest.TestCase):
    def ptr(self, last):
        return {"open_case_id": "tok_1#A", "last_flag_ts": Decimal(str(last))}

    def test_first_flag_opens_case_named_after_event(self):
        self.assertEqual(choose_case(None, "tok_1", T0), f"tok_1#{int(T0 * 1000)}")

    def test_crossing_clock_boundary_stays_one_case(self):   # the old bucket bug
        self.assertEqual(choose_case(self.ptr(T0), "tok_1", T0 + 20), "tok_1#A")

    def test_gap_over_30_min_opens_new_case(self):
        self.assertEqual(choose_case(self.ptr(T0), "tok_1", T0 + 1801), f"tok_1#{int((T0 + 1801) * 1000)}")

    def test_replayed_older_event_joins_current_case(self):
        self.assertEqual(choose_case(self.ptr(T0), "tok_1", T0 - 60), "tok_1#A")

    def test_deterministic(self):
        self.assertEqual(choose_case(None, "tok_1", T0), choose_case(None, "tok_1", T0))


if __name__ == "__main__":
    unittest.main()
